B.a04=s(["Na spodnjem delu podlage sta skali \xb0C (notranja) in \xb0F (zunanja).","Poi\u0161\u010di vrednost na eni skali in preberi sosednjo vrednost na drugi."],t.s)
B.XE=s(["+15 \xb0C stoji ob +59 \xb0F.","\u221210 \xb0C stoji ob +14 \xb0F."],t.s)
B.T7=new A.fP("Temperatura \xb0C \u2194 \xb0F","Skali na spodnjem delu podlage, disk ni potreben.",!0,B.a04,B.XE,"+15 \xb0C = +59 \xb0F")
B.a6H=s(["Na vi\u0161inomeru nastavi 1013 hPa in preberi tla\u010dno vi\u0161ino (PA).","V okencu za hitrost (POPRAVEK HITROSTI) zavrti disk, da je zunanja temperatura (AIR TEMP.) nasproti tla\u010dne vi\u0161ine.","Nad CAS na notranji skali preberi TAS na zunanji skali.","V okencu DENSITY ALT pod \u25b2 preberi gostotno vi\u0161ino."],t.s)
B.a5J=s(["PA 2000 ft, OAT +30 \xb0C, CAS 100 km/h.","+30 v okencu postavi nasproti 2 (\xd71000 ft).","Nad 100 na notranji skali preberi pribli\u017eno 106.","Pod \u25b2 v okencu DENSITY ALT preberi pribli\u017eno 4,2 (\xd71000 ft)."],t.s)
B.T6=new A.fP("Prava hitrost (TAS) in gostotna vi\u0161ina","Popravek CAS za tla\u010dno vi\u0161ino in temperaturo.",!0,B.a6H,B.a5J,"TAS \u2248 106 km/h, gostotna vi\u0161ina \u2248 4200 ft")
B.XF=s(["V okencu za vi\u0161ino (POPRAVEK VI\u0160INE) zavrti disk, da je zunanja temperatura na vi\u0161ini leta nasproti tla\u010dne vi\u0161ine.","Nad kalibrirano (indicirano) vi\u0161ino na notranji skali preberi pravo vi\u0161ino na zunanji skali.","V hladnej\u0161em zraku od standardnega je prava vi\u0161ina ni\u017eja od indicirane, v toplej\u0161em vi\u0161ja."],t.s)
B.a5A=s(["PA 6000 ft, OAT \u22125 \xb0C, indicirana vi\u0161ina 6000 ft.","\u22125 v okencu postavi nasproti 6 (\xd71000 ft).","Nad 60 na notranji skali preberi pribli\u017eno 58,2."],t.s)
B.T9=new A.fP("Prava vi\u0161ina","Popravek vi\u0161ine za temperaturo zraka.",!0,B.XF,B.a5A,"Prava vi\u0161ina \u2248 5820 ft (\u2248 180 ft ni\u017eje)")
B.a1V=s(["Smer vetra (od koder piha) zavrti pod TRUE INDEX.","Drsnik premakni, da je sredi\u0161\u010de na okrogli hitrosti (npr. 100).","Nad sredi\u0161\u010dem na sredinski \u010drti s tapom ozna\u010di hitrost vetra (pri 20 kt vetra oznaka pri 120).","Pravi kurz (TC) zavrti pod TRUE INDEX.","Drsnik premakni, da je oznaka na loku TAS.","Pod sredi\u0161\u010dem preberi GS.","Stopinje med sredinsko \u010drto in oznako so WCA: oznaka levo pomeni WCA levo, desno pomeni WCA desno.","TH = TC \u2212 WCA L oziroma TC + WCA R."],t.s)
B.a32=s(["TC 090\xb0, TAS 100 kt, veter 030\xb0 / 20 kt.","030 pod TRUE INDEX, sredi\u0161\u010de na 100, oznaka pri 120.","090 pod TRUE INDEX, drsnik premakni, da je oznaka na loku 100.","Pod sredi\u0161\u010dem preberi pribli\u017eno 88, oznaka je 10\xb0 levo.","TH = 090\xb0 \u2212 10\xb0 = 080\xb0."],t.s)
